    "post": {
      "operationId": "InitializeUserRegistration_initializeRegistration",
      "summary": "Initialize the registration of a User",
      "description": "Initialize the registration of a User at the API Hub for services such as CAAP.\n\nThis is implemented as an RPC operation to remove any requirement for LFIs \nto implement a REST model for their Users, which is subject to significant variance across\nproviders.\n\nThe response status indicates next steps to the API Hub. If the `Complete` status is returned\nthen no step-up is feasible or is required, and the complete operation can be omitted.\n\nIf resolution of the User at the LFI an error response MUST be returned, in line with guidance\non HTTP response codes and error structures prescribed by Ozone Connect.",
      "parameters": [],
      "responses": {
        "201": {
          "description": "The request has succeeded and a new resource has been created as a result.",
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "data": {
                    "$ref": "#/components/schemas/OzoneConnectInitializeUserRegistrationResponseBody"
                  }
                },
                "required": [
                  "data"
                ]
              }
            }
          }
        },
        "400": {
          "$ref": "#/components/responses/error400Response"
        },
        "403": {
          "$ref": "#/components/responses/error403Response"
        },
        "409": {
          "$ref": "#/components/responses/error409Response"
        },
        "500": {
          "$ref": "#/components/responses/error500Response"
        },
        "default": {
          "$ref": "#/components/responses/errorResponse"
        }
      },
      "tags": [
        "User Registration"
      ],
      "requestBody": {
        "required": true,
        "content": {
          "application/json": {
            "schema": {
              "type": "object",
              "properties": {
                "data": {
                  "$ref": "#/components/schemas/OzoneConnectInitializeUserRegistrationRequestBody"
                }
              },
              "required": [
                "data"
              ]
            }
          }
        }
      }
    }
  },
